function devLog(msg) {
  const log = document.getElementById("wz-dev-log");
  if (!log) return;
  const line = document.createElement("div");
  line.textContent = `${new Date().toLocaleTimeString()} ${msg}`;
  log.prepend(line);
  while (log.children.length > 20) {
    log.removeChild(log.lastChild);
  }
}
